D[6898]={"^Gain Armor based on your Spirit for (.-)%.%s*$","Ganha armadura baseada em seu Espírito durante {{1}}."}
D[6899]={"^Increases an ally's attack power based on your Spirit for (.-)%.%s*$","Aumenta o poder de ataque de um aliado baseado em seu Espírito durante {{1}}."}
D[6900]={"^Gain spell power based on your Spirit for (.-)%.%s*$","Ganha Poder Mágico baseado em seu Espírito durante {{1}}."}
