D[11161]={"^Increases an ally's Arcane damage by (.-)%% for (.-)%.%s*$","Aumenta o dano Arcano de um aliado em {{1}}% durante {{2}}."}
D[11162]={"^Increases an ally's Fire damage by (.-)%% for (.-)%.%s*$","Aumenta o dano de Fogo de um aliado em {{1}}% durante {{2}}."}
