D[12444]={"^Protected by the twisted magic of Karazhan%.\n\nDamage taken reduced by (.-)%% for (.-)%.%s*$","Protegido pela magia retorcida de Karazhan.\n\nO dano recebido é reduzido em {{1}}% durante {{2}}."}
D[12445]={"^Inlicts (.-) Fire damage to a target%.%s*$","causa {{1}} de dano de Fogo um alvo."}
